# All nine left cycles are complete and the left gripper is clear of the cap.
# Return the left arm home and align the right arm above blue for the first confirmation.
def return_home(max_steps):
    for index in range(max_steps):
        obs, reward, terminated, truncated, info = step(origin_action)
        error = max(abs(float(obs['state'][key][j]) - float(origin_action[key][j]))
                    for key in ['left_arm_joint_state', 'right_arm_joint_state']
                    for j in range(len(origin_action[key])))
        if terminated or truncated or (index >= 9 and error < 0.005):
            return {'steps': index + 1, 'error': error, 'reward': reward,
                    'terminated': terminated, 'truncated': truncated}
    return {'steps': max_steps, 'error': error, 'reward': reward,
            'terminated': terminated, 'truncated': truncated}
